/*
 * dap_csm.c -- CSM digital autopilot against the real AGC code (yaAGC).
 *
 * Inputs and expected words: tools/oracle/cases/dap_csm.spec / .txt
 * (Comanche055), generated by tools/oracle/cases/gen/gen_dap_csm.py.
 * Jet selection (JETSLECT through CALCDT6: the PYTABLE/RTABLE/YZTABLE
 * look-up, quad failures, on-time limits and the sorted T6 intervals), one
 * TVC pitch sample (PITCHDAP: CDU rates, body rate, error integral, the
 * three-cascade filter with VARK, offset tracker, copycycle) and ROLLDAP
 * (the TVC roll phase-plane logic).
 *
 * Tolerances (LSB of the AGC word): see docs/modules/oracle-cases.md.
 */
#include <stdio.h>

#include <string.h>

#include "../../src/csm/dap/internal.h"
#include "agc/core/assert.h"
#include "agc/core/interp.h"
#include "agc/core/state.h"
#include "agc/csm/dap.h"
#include "agc/exec/exec.h"
#include "agc/guidance/guidance.h"
#include "oracle_txt.h"

bool agc_assert_report(const char *file, int line, const char *expr)
{
    (void) printf("assert %s:%d %s\n", file, line, expr);

    return (false);
}

static void cmp_raw(const char *t, const char *what, unsigned got,
                    const char *n)
{
    (void) oracle_cmp(t, what, (long) got, (long) oracle_out_raw(t, n), 0);
}

static void cmp_sp(const char *t, const char *what, long got, const char *n,
                   long tol)
{
    (void) oracle_cmp(t, what, got, oracle_out_sp(t, n), tol);
}

static void fresh(void)
{
    agc_state_init(AGC_VEHICLE_CSM);
    (void) agc_exec_init();
    (void) agc_waitlist_init();
    (void) agc_guid_init(AGC_VEHICLE_CSM);
    /* each AGC run starts from zeroed erasable: no leftovers from the
     * previous case in the DAP blocks (temporaries such as DELOGA)       */
    (void) memset(agc_csm_dap_tvc(), 0, sizeof (agc_csm_tvc_t));
    (void) memset(agc_csm_dap_rcs(), 0, sizeof (agc_csm_rcs_t));
    (void) memset(agc_csm_dap_com(), 0, sizeof (agc_csm_dapcom_t));
}

static void jets(const char *t)
{
    agc_csm_jet_in_t         in;
    agc_csm_jet_out_t        o;
    static const char *const bl[3] = {"BLAST", "BLAST1", "BLAST2"};

    in.chan31 = 077777; /* yaAGC power-up: no THC command */
    in.lem_on = (oracle_in_raw(t, "DAPDATR1", 0) & 020000u) != 0;

    for (int k = 0; k < 3; k++)
    {
        in.tau[k] = (agc_sp_t) oracle_in(t, "TAU", k);
    }

    in.racfail = (agc_sp_t) oracle_in(t, "RACFAIL", 0);
    in.rbdfail = (agc_sp_t) oracle_in(t, "RACFAIL", 1);
    in.acorbd  = (agc_sp_t) oracle_in(t, "RACFAIL", 2);
    in.xtrans  = (agc_sp_t) oracle_in(t, "RACFAIL", 3);
    (void) agc_csm_jet_select(&in, &o);
    oracle_require_ok(t, "ENDJETS");
    cmp_raw(t, "RWORD1", o.rword1, "RWORD1");
    cmp_raw(t, "RWORD2", o.rword2, "RWORD2");
    cmp_raw(t, "PWORD1", o.pword1, "PWORD1");
    cmp_raw(t, "PWORD2", o.pword2, "PWORD2");
    cmp_raw(t, "YWORD1", o.yword1, "YWORD1");
    cmp_raw(t, "YWORD2", o.yword2, "YWORD2");

    for (int k = 0; k < 3; k++)
    {
        char lo[16];
        char d[8];

        (void) snprintf(lo, sizeof lo, "%s+1", bl[k]);
        cmp_sp(t, bl[k], o.blast[k].time, bl[k], 0);
        cmp_sp(t, lo, (long) o.blast[k].axis, lo, 0);
        (void) snprintf(d, sizeof d, (k == 0) ? "DFT" : "DFT%d", k);
        cmp_sp(t, d, o.dft[k], d, 0);
        (void) snprintf(d, sizeof d, (k == 0) ? "TAU" : "TAU%d", k);
        cmp_sp(t, d, o.tau[k], d, 0);
    }

    if (o.attkalmn_xln != 0x7FFF)
    {
        cmp_sp(t, "ATTKALMN", o.attkalmn_xln, "ATTKALMN", 0);
    }
}

static void pitch(const char *t, long tol)
{
    agc_csm_tvc_t *v = agc_csm_dap_tvc();
    agc_cdutrig_t *g;

    fresh();
    g = &agc_guid_state()->trig;
    agc_erase_set_cduy(oracle_in_raw(t, "CDUY", 0));
    agc_erase_set_cduz(oracle_in_raw(t, "CDUY", 1));
    v->pcduypst           = oracle_in_raw(t, "PCDUYPST", 0);
    v->pcduzpst           = oracle_in_raw(t, "PCDUYPST", 1);
    v->perrb              = csm_dap_pair(oracle_in_dp(t, "PERRB", 0));
    v->omegac[1]          = oracle_in_dp(t, "OMEGAYC", 0);
    g->sincdu[AGC_TRIG_X] =
        agc_dp_from_sp((agc_sp_t) oracle_in(t, "SINCDUX", 0));
    g->coscdu[AGC_TRIG_X] =
        agc_dp_from_sp((agc_sp_t) oracle_in(t, "COSCDUX", 0));
    g->coscdu[AGC_TRIG_Z] =
        agc_dp_from_sp((agc_sp_t) oracle_in(t, "COSCDUZ", 0));

    for (int k = 0; k < 6; k++)
    {
        v->ptmp[k] = csm_dap_pair(oracle_in_dp(t, "PTMP1", 2 * k));
    }

    for (int k = 0; k < AGC_CSM_N10_WORDS; k++)
    {
        v->n10[k] = (agc_sp_t) oracle_in(t, "N10", k);
    }

    v->vark     = (agc_sp_t) oracle_in(t, "VARK", 0);
    v->pdeloff  = csm_dap_pair(oracle_in_dp(t, "PDELOFF", 0));
    v->pcmd     = (agc_sp_t) oracle_in(t, "PCMD", 0);
    v->delpbar  = csm_dap_pair(oracle_in_dp(t, "DELPBAR", 0));
    v->stroker  = 0;
    v->t5tvcdt  = (agc_sp_t) oracle_in(t, "T5TVCDT", 0);
    v->tvcphase = 0;
    agc_erase_set_tvcpitch((agc_sp_t) oracle_in(t, "TVCPITCH", 0));
    agc_erase_set_dapdatr1(oracle_in_raw(t, "DAPDATR1", 0));
    (void) agc_task_pitchdap();
    oracle_require_ok(t, "RESUME");
    cmp_sp(t, "MCDUYDOT", v->mcduydot, "MCDUYDOT", 0);
    cmp_sp(t, "MCDUZDOT", v->mcduzdot, "MCDUZDOT", 0);
    (void) oracle_cmp(t, "OMEGAYB", csm_dap_pair_value(v->omegab[1]), oracle_out_dp(t, "OMEGAYB"),
                      tol);
    (void) oracle_cmp(t, "PERRB", csm_dap_pair_value(v->perrb), oracle_out_dp(t, "PERRB"), tol);

    for (int k = 0; k < 6; k++)
    {
        char n[16];

        (void) snprintf(n, sizeof n, (k == 0) ? "PTMP1" : "PTMP1+%d", 2 * k);
        (void) oracle_cmp(t, n, csm_dap_pair_value(v->ptmp[k]), oracle_out_dp(t, n), tol);
    }

    /* F9: CMDTMP and ERRBTMP are DAS results the AGC leaves sign-
     * disagreeing (e.g. 77765 00356) and then uses by their high word:
     * PCMD, the TVCPITCH increment and AK1 differ by one high-word LSB,
     * DELPBAR by (1 - E(-AT)) of that.                                   */
    oracle_cmp_known(t, "PCMD", v->pcmd, oracle_out_sp(t, "PCMD"), 0, "F9");
    oracle_cmp_known(t, "DELPBAR", csm_dap_pair_value(v->delpbar), oracle_out_dp(t, "DELPBAR"),
                     tol, "F9");
    oracle_cmp_known(t, "TVCPITCH", agc_erase_tvcpitch(),
                     oracle_out_sp(t, "TVCPITCH"), 0, "F9");
    oracle_cmp_known(t, "AK1", agc_csm_dap_com()->ak[1],
                     oracle_out_sp(t, "AK1"), 0, "F9");
    cmp_sp(t, "TVCPHASE", v->tvcphase, "TVCPHASE", 0);
    cmp_raw(t, "PCDUYPST", v->pcduypst, "PCDUYPST");
    cmp_raw(t, "PCDUZPST", v->pcduzpst, "PCDUZPST");
}

static void roll(const char *t)
{
    agc_csm_tvc_t *v = agc_csm_dap_tvc();

    fresh();
    v->oganow     = oracle_in_raw(t, "OGANOW", 0);
    v->ogapast    = oracle_in_raw(t, "OGANOW", 1);
    v->rollfire   = (agc_sp_t) oracle_in(t, "ROLLFIRE", 0);
    v->rollword   = oracle_in_raw(t, "ROLLFIRE", 1);
    v->temreg     = (agc_sp_t) oracle_in(t, "ROLLFIRE", 2);
    v->one_conacc = (agc_sp_t) oracle_in(t, "E6,1640", 0);
    v->ogaerr     = (agc_sp_t) oracle_in(t, "OGA", 0);
    agc_rupt_set_time(CSM_DAP_TIME6, oracle_in_raw(t, "TIME6", 0));
    (void) agc_task_rolldap();
    oracle_require_ok(t, "TASKOVER");
    cmp_sp(t, "OGARATE", v->ogarate, "OGARATE", 0);
    cmp_sp(t, "TEMREG", v->temreg, "TEMREG", 0);
    cmp_sp(t, "ROLLFIRE", v->rollfire, "ROLLFIRE", 0);
    cmp_raw(t, "ROLLWORD", v->rollword, "ROLLWORD");
    cmp_sp(t, "DELOGA", v->deloga, "DELOGA", 0);
    cmp_sp(t, "DELOGART", v->delogart, "DELOGART", 0);
    cmp_sp(t, "SGNRT", v->sgnrt, "SGNRT", 0);
    cmp_sp(t, "IOGARATE", v->iogarate, "IOGARATE", 0);
    cmp_raw(t, "TIME6", agc_rupt_time(CSM_DAP_TIME6), "TIME6");
}

int main(void)
{
    if (!oracle_load("dap_csm"))
    {
        (void) printf("oracle_dap_csm: SKIP (case files not found)\n");

        return (0);
    }

    fresh();
    jets("jets_pitch");
    jets("jets_all");
    jets("jets_long");
    jets("jets_fail_a");
    jets("jets_fail_cd");
    jets("jets_short");
    pitch("pitch_quiet", 4);
    pitch("pitch_rate", 4);
    pitch("pitch_lm", 4);
    pitch("pitch_big", 4);
    roll("roll_coast");
    roll("roll_start");
    roll("roll_neg");
    roll("roll_firing");
    roll("roll_wait");
    roll("roll_ratelim");

    return (oracle_finish("oracle_dap_csm"));
}
